{"path": "src/index.js", "content": "const express = require('express');
const morgan = require('morgan');
const { connect } = require('./db');
const { addToCart } = require('./service');

const app = express();
app.use(express.json());
app.use(morgan('dev'));

app.post('/cart/:userId/add', async (req, res) => {
  const userId = req.params.userId;
  const { productId, quantity } = req.body;
  if (!productId || !quantity || quantity <= 0) {
    return res.status(400).json({ error: 'productId and quantity>0 required' });
  }

  try {
    const result = await addToCart(userId, productId, quantity);
    if (!result.success) {
      if (result.error === 'OutOfStock') return res.status(409).json({ error: 'OutOfStock' });
      return res.status(500).json({ error: result.error });
    }
    return res.json({ cart: result.cart });
  } catch (err) {
    console.error(err);
    return res.status(500).json({ error: 'internal' });
  }
});

const port = process.env.PORT || 3000;
(async () => {
  await connect();
  app.listen(port, () => {
    console.log('Server listening on', port);
  });
})();
"}

{"path": "src/seed.js", "content": "const { connect, mongoose } = require('./db');
const { Inventory, Cart } = require('./models');

async function seed() {
  await connect();

  const products = [
    { sku: 'SKU-RED-001', name: 'Red T-Shirt', price: 19.99, stock: 5 },
    { sku: 'SKU-BLU-002', name: 'Blue Jeans', price: 49.99, stock: 2 },
    { sku: 'SKU-HAT-003', name: 'Cap', price: 12.5, stock: 10 }
  ];

  for (const p of products) {
    await Inventory.updateOne({ sku: p.sku }, { $set: p }, { upsert: true });
  }

  // Ensure a cart exists for demo user 'alice'
  await Cart.updateOne({ userId: 'alice' }, { $setOnInsert: { userId: 'alice', items: [] } }, { upsert: true });

  // Ensure indexes are created
  await Inventory.createCollection().catch(()=>{});
  await Cart.createCollection().catch(()=>{});
  await Inventory.syncIndexes();
  await Cart.syncIndexes();

  console.log('Seed complete');
  process.exit(0);
}

seed().catch(err=>{ console.error(err); process.exit(1); });
"}

{"path": "src/demo.js", "content": "const { connect } = require('./db');
const { Inventory } = require('./models');
const { addToCart } = require('./service');

async function demo() {
  await connect();
  // pick a product to test
  const prod = await Inventory.findOne({ sku: 'SKU-BLU-002' });
  if (!prod) { console.error('seed first (npm run seed)'); process.exit(1); }

  console.log('Product before:', prod.sku, 'stock=', prod.stock);

  // try to add more than stock to show clear error
  const overQty = prod.stock + 5;
  const r = await addToCart('alice', prod._id, overQty);
  console.log('Attempt add over stock result:', r);

  // now add a valid amount
  const okR = await addToCart('alice', prod._id, 1);
  console.log('Add 1 result:', okR.success ? 'ok' : okR);

  const after = await Inventory.findById(prod._id);
  console.log('Product after:', after.sku, 'stock=', after.stock);

  process.exit(0);
}

demo().catch(err=>{ console.error(err); process.exit(1); });
"}

